    private static void timelineBatch(RecordStore db,File wav)throws Exception{
        ArrayList<String> sources=new ArrayList<>();long base=System.currentTimeMillis()-20*3600000L;JSONObject provider=new JSONObject().put("endpoint","https://example.invalid/v1").put("model","synthetic");
        try{
            JSONArray ids=new JSONArray();for(int i=0;i<127;i++){String id=db.importUri(Uri.fromFile(wav));sources.add(id);db.getWritableDatabase().execSQL("UPDATE audio SET created=?,duration=300000,metadata=? WHERE id=?",new Object[]{base+i*300000L,new JSONObject().put("session_id","all-day").toString(),id});if(i>0)db.update("audio",id,"transcript","讨论第"+i+"个方案，需要核对来源。");ids.put(id);}
            JSONArray rows=db.rows("SELECT * FROM audio WHERE created>=? AND created<? ORDER BY created",String.valueOf(base),String.valueOf(base+127*300000L));check(EventTimeline.group(rows).size()>=22,"627 minute recording cannot collapse into one pending card");
            String job=db.addJob("","analysis_batch",new JSONObject().put("sources",ids).put("provider",provider));check(!job.isEmpty(),"127 sources enqueue through batch path even when first transcript is empty");
            JSONArray jobs=db.rows("SELECT * FROM jobs WHERE status='queued' AND type='analysis' ORDER BY created,rowid");Set<String> seen=new HashSet<>();int batches=0;for(int i=0;i<jobs.length();i++){JSONObject input=new JSONObject(jobs.getJSONObject(i).getString("input"));JSONArray selected=input.getJSONArray("sources");if(!sources.contains(selected.getString(0)))continue;batches++;check(selected.length()<=8&&input.getJSONObject("analysis_snapshot").toString().length()<=65000,"each queued batch fits actual serialized snapshot budget");for(int n=0;n<selected.length();n++)check(seen.add(selected.getString(n)),"batch covers each source once");}check(batches==16&&seen.size()==126&&!seen.contains(sources.get(0)),"all valid transcripts covered, empty source skipped");
            String source=sources.get(1);JSONObject snapshot=AnalysisPipeline.snapshot(db,new JSONArray().put(source));String unit=snapshot.getJSONArray("units").getJSONObject(0).getString("unit_id");JSONObject ctx=LifeMemory.context(db,snapshot);JSONObject extracted=AnalysisPipeline.validate(new JSONObject().put("facts",new JSONArray()).put("paragraphs",new JSONArray().put(new JSONObject().put("unit_ids",new JSONArray().put(unit)).put("action","NEW_EVENT"))),snapshot);JSONObject result=AnalysisPipeline.finish(extracted,new JSONObject().put("summary","核对方案").put("paragraphs",new JSONArray().put(new JSONObject().put("title","方案核对").put("summary","讨论并核对方案来源。"))),snapshot);LifeMemory.save(db,result,ctx);
            int events=0;for(EventTimeline.Item item:EventTimeline.items(db,rows))if(item.event!=null){events++;check(item.event.getString("title").equals("方案核对"),"archive displays actual semantic title");}check(events==1,"archive loads validated event units without requiring first-file cached analysis");
            db.update("audio",source,"transcript","原文已纠正，之前语义事件不再有效。");events=0;for(EventTimeline.Item item:EventTimeline.items(db,rows))if(item.event!=null)events++;check(events==0,"stale event excluded from timeline after correction");
            boolean empty=false;int before=db.rows("SELECT id FROM jobs").length();try{db.addJob("","analysis_batch",new JSONObject().put("sources",new JSONArray().put(sources.get(0))).put("provider",provider));}catch(IOException e){empty=e.getMessage().contains("转写");}check(empty&&db.rows("SELECT id FROM jobs").length()==before,"empty transcript reports actionable reason and leaves no partial tasks");
            String denseA=sources.get(4),denseB=sources.get(5);for(String dense:new String[]{denseA,denseB}){JSONArray segments=new JSONArray();StringBuilder transcript=new StringBuilder();for(int i=0;i<110;i++){String words="核对具体项目的设计方案和执行安排，确认需求后再推进下一步工作。"+i;transcript.append(words);segments.put(new JSONObject().put("start_ms",i*2500).put("end_ms",i*2500+2000).put("speaker","说话人 1").put("text",words));}db.editSpeech(dense,db.audio(dense).optLong("transcript_revision"),new JSONObject().put("text",transcript.toString()).put("segments",segments));}
            JSONArray denseIds=new JSONArray().put(denseB).put(denseA);String denseJob=db.addJob("","analysis_batch",new JSONObject().put("sources",denseIds).put("provider",provider));JSONObject denseInput=new JSONObject(db.rows("SELECT input FROM jobs WHERE id=?",denseJob).getJSONObject(0).getString("input"));check(denseInput.getJSONArray("sources").getString(0).equals(denseA),"batch sorts selected sources chronologically");check(denseInput.getJSONObject("analysis_snapshot").toString().length()<=65000,"dense timed metadata fits snapshot budget");
            // Long text passes raw character heuristic but exceeds serialized unit budget.
            String big=sources.get(2),other=sources.get(3);StringBuilder text=new StringBuilder();for(int i=0;i<12000;i++)text.append("讨论方案");db.update("audio",big,"transcript",text.toString());before=db.rows("SELECT id FROM jobs").length();boolean rejected=false;try{db.addJob("","analysis_batch",new JSONObject().put("sources",new JSONArray().put(other).put(big)).put("provider",provider));}catch(IOException e){rejected=true;}check(rejected&&db.rows("SELECT id FROM jobs").length()==before,"oversized single source rolls back entire queue creation");
        }finally{for(String id:sources)db.forget(id);}
    }
