            if(stage==0){JSONObject unit=data.getJSONArray("units").getJSONObject(0);answer=new JSONObject().put("facts",new JSONArray().put(new JSONObject().put("type","task").put("text","提交测试方案").put("unit_id",unit.getString("unit_id")).put("quote",unit.getString("text")))).put("paragraphs",new JSONArray().put(new JSONObject().put("unit_ids",new JSONArray().put(unit.getString("unit_id"))).put("action","NEW_EVENT")));}
            else if(stage==1||stage==2){answer=new JSONObject().put("decisions",new JSONArray().put(new JSONObject().put("index",0).put("action","KEEP").put("reason","明确待办，保留").put("context_reviewed",true).put("unique_information",true)));}
            else if(stage==3){check(data.getJSONArray("facts").getJSONObject(0).getString("quote").contains("提交"),"second model call consumes verified facts");answer=new JSONObject().put("summary","约定提交方案").put("paragraphs",new JSONArray().put(new JSONObject().put("title","方案提交").put("summary","原话约定提交测试方案。")));}
            else{JSONArray evidence=data.getJSONArray("evidence");answer=new JSONObject().put("claims",new JSONArray().put(new JSONObject().put("section","task").put("kind","observed").put("text","记录里提出提交测试方案，仍待核对。 ").put("evidence_ids",new JSONArray().put(evidence.getJSONObject(0).getString("id"))))).put("questions",new JSONArray().put("方案是否已提交？"));}
            requests[0]++;String body=new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",answer.toString())))).toString();byte[] output=body.getBytes("UTF-8");OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 "+(stage==1?"503 Service Unavailable":"200 OK")+"\r\nContent-Type: application/json\r\nContent-Length: "+output.length+"\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));out.write(output);
