        android.content.SharedPreferences prefs=c.getSharedPreferences("network-policy",0);boolean previous=prefs.getBoolean("allow_local_http",false);SecureSettings settings=new SecureSettings(c);String role="pipeline-test";
        try(RecordStore db=new RecordStore(c)){prefs.edit().putBoolean("allow_local_http",true).commit();settings.saveProvider(role,"http://127.0.0.1:"+server.getLocalPort()+"/v1","test-model","",false);String source=db.importUri(Uri.fromFile(wav));db.update("audio",source,"transcript","我明天提交测试方案。");JSONObject provider=new ProviderClient(c).snapshot(role);String job=db.addJob(source,"analysis",new JSONObject().put("provider",provider).put("transcript",db.audio(source).getString("transcript")));c.startForegroundService(new Intent(c,AgentService.class));boolean filterFailed=false;try{await(db,job);}catch(IOException expected){filterFailed=true;}check(filterFailed,"filter API failure is recorded without automatic retry");JSONObject retry=new JSONObject(db.rows("SELECT input FROM jobs WHERE id=?",job).getJSONObject(0).getString("input"));check(retry.getJSONObject("pipeline_cache").has("extraction"),"validated extraction is persisted before downstream failure");job=db.addJob(source,"analysis",retry);c.startForegroundService(new Intent(c,AgentService.class));await(db,job);check(db.rows("SELECT * FROM atomic_facts WHERE source=?",source).length()==1,"real durable service saves atomic extraction");check(new JSONObject(db.audio(source).getString("analysis")).getJSONArray("paragraphs").getJSONObject(0).getString("title").equals("方案提交"),"real service saves named semantic paragraph");
            long now=System.currentTimeMillis();String review=db.addJob("","life_review",new JSONObject().put("provider",provider).put("kind","daily").put("start",now-60000).put("end",now+60000));c.startForegroundService(new Intent(c,AgentService.class));await(db,review);check(db.rows("SELECT * FROM life_reviews WHERE id=?",review).length()==1,"real durable service persists grounded daily review");check(requests[0]==5,"explicit retry reuses cached extraction: one extraction, two filters, one summary and one review");mock.join(1000);if(failure[0]!=null)throw new IOException(failure[0]);db.forget(source);
        }finally{server.close();prefs.edit().putBoolean("allow_local_http",previous).commit();settings.saveProvider(role,"","","",true);}
